def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write_complete(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def main() -> int:
    print("=" * 40)
    print(" OOR-012 INSTALLER")
    print(" CONTINUATION ATTESTATION GATE")
    print("=" * 40)
    try:
        if not SOURCE.is_file():
            raise RuntimeError(f"Actual OOR-011 module missing: {SOURCE}")
        source_text = SOURCE.read_text(encoding="utf-8")
        required = (
            'SCHEMA_VERSION = "OOR-011"',
            "OracleOperatorRuntimeSessionActivationContinuation",
            "CONTINUATION_TYPE",
            "CONTINUATION_STATUS",
            "continuation_hash",
            "continued_at",
        )
        missing = [item for item in required if item not in source_text]
        if missing:
            raise RuntimeError(f"OOR-011 contract incomplete: {missing}")
        ast.parse(source_text, filename=str(SOURCE))
        protected_hash = sha256(SOURCE)
        print("[OK] Actual OOR-011 activation continuation contract verified")

        write_complete(PRODUCTION, PRODUCTION_SOURCE)
        write_complete(TEST, TEST_SOURCE)

        export = (
            "from qseries_v2.oracle_operator_runtime."
            "oracle_operator_runtime_session_activation_continuation_attestation_gate import ("
            "OracleOperatorRuntimeSessionActivationContinuationAttestation, "
            "OracleOperatorRuntimeSessionActivationContinuationAttestationGate, "
            "OracleOperatorRuntimeSessionActivationContinuationAttestationInvariantError)"
        )
        current = (
            INIT.read_text(encoding="utf-8")
            if INIT.exists()
            else "from __future__ import annotations\n"
        )
        if export not in current:
            INIT.write_text(
                current.rstrip() + "\n" + export + "\n",
                encoding="utf-8",
                newline="\n",
            )
        ast.parse(INIT.read_text(encoding="utf-8"), filename=str(INIT))
        print(f"[OK] PACKAGE UPDATED: {INIT.resolve()}")

        completed = subprocess.run([sys.executable, str(TEST)], cwd=ROOT, check=False)
        if completed.returncode:
            raise RuntimeError(f"OOR-012 test failed with exit code {completed.returncode}")
        if sha256(SOURCE) != protected_hash:
            raise RuntimeError("Protected OOR-011 module changed")

        print("[PASS] Protected OOR-011 module unchanged")
        print("[PASS] OOR-001 through OOR-011 lineage preserved")
        print("[PASS] No acquisition, analytics, Oracle Operator, or Q Series execution module modified")
        print(f"[PASS] Repository located: {ROOT}")
        print("[DONE] OOR-012 INSTALLED AND VERIFIED")
        return 0
    except (RuntimeError, SyntaxError) as exc:
        print(f"[ERROR] {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
